/// Add default route with `onlink` flag via native netlink.
///
/// Required when the output interface is an OVS internal port: the kernel
/// cannot verify gateway reachability until OVS is forwarding, so we must
/// bypass nexthop validation.  We build the `RTM_NEWROUTE` message manually
/// using `netlink-packet-route` so that the `RTNH_F_ONLINK` (0x01) flag is
/// set in the nexthop attribute — the high-level `rtnetlink` crate does not
/// expose this flag through its typed builder.
pub async fn add_default_route_onlink(ifname: &str, gateway: &str) -> Result<()> {
    use netlink_packet_core::{
        NetlinkHeader, NetlinkMessage, NetlinkPayload, NLM_F_ACK, NLM_F_CREATE, NLM_F_REPLACE,
        NLM_F_REQUEST,
    };
    use netlink_packet_route::{
        route::{
            RouteAddress, RouteAttribute, RouteHeader, RouteMessage, RouteProtocol,
            RouteScope, RouteType,
        },
        AddressFamily, RouteNetlinkMessage,
    };
    use netlink_packet_utils::nla::DefaultNla;
    use netlink_sys::{protocols::NETLINK_ROUTE, Socket};

    // Resolve interface index
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    let gw: Ipv4Addr = gateway.parse().context("Invalid gateway address")?;

    // Build the route message manually.
    let mut route_msg = RouteMessage::default();
    route_msg.header = RouteHeader {
        address_family: AddressFamily::Inet,
        destination_prefix_length: 0,
        source_prefix_length: 0,
        tos: 0,
        table: 254, // RT_TABLE_MAIN
        protocol: RouteProtocol::Static,
        scope: RouteScope::Link, // RT_SCOPE_LINK — onlink semantics
        kind: RouteType::Unicast,
        flags: Vec::new(),
    };

    // Standard single-path attributes.
    route_msg.attributes.push(RouteAttribute::Destination(
        RouteAddress::Inet(Ipv4Addr::new(0, 0, 0, 0)),
    ));
    route_msg
        .attributes
        .push(RouteAttribute::Gateway(RouteAddress::Inet(gw)));
    route_msg.attributes.push(RouteAttribute::Oif(ifindex));

    // --- RTNH_F_ONLINK encoding ------------------------------------------
    // The `rtnetlink` crate does not expose per-nexthop flags through its
    // builder API.  `RTNH_F_ONLINK` (0x01) belongs to the `rtnh_flags` field
    // of the `rtnexthop` struct that is nested inside `RTA_NEXTHOP`.
    //
    // For single-path routes iproute2 still emits `RTA_NEXTHOP` when any
    // nexthop flag is set.  `netlink-packet-route` 0.19 does not yet expose
    // a typed `RouteAttribute::NextHop` variant, so we encode the raw
    // bytes by hand:
    //   struct rtnexthop { __u16 rtnh_len; __u8 rtnh_flags; __u8 rtnh_hops;
    //                      __u32 rtnh_ifindex; }
    //   followed by nested attributes (RTA_GATEWAY, RTA_OIF).
    // -------------------------------------------------------------------
    let mut nh_buf = Vec::new();
    // rtnh_len: will be back-patched after we know the total size
    nh_buf.extend_from_slice(&[0, 0]); // placeholder
    // rtnh_flags = RTNH_F_ONLINK (0x01)
    nh_buf.push(0x01);
    // rtnh_hops = 0
    nh_buf.push(0x00);
    // rtnh_ifindex = ifindex (native endian)
    nh_buf.extend_from_slice(&ifindex.to_ne_bytes());

    // Nested gateway attribute inside nexthop: RTA_GATEWAY (1) + length + value
    let gw_bytes = gw.octets();
    let gw_attr_len: u16 = (4 + 4 + gw_bytes.len()) as u16; // 4 header + 4 padding alignment
    nh_buf.extend_from_slice(&gw_attr_len.to_ne_bytes());
    nh_buf.extend_from_slice(&(1u16).to_ne_bytes()); // RTA_GATEWAY type = 1
    nh_buf.extend_from_slice(&gw_bytes);
    // Align to 4 bytes
    while nh_buf.len() % 4 != 0 {
        nh_buf.push(0);
    }

    // Back-patch rtnh_len
    let nh_total = nh_buf.len() as u16;
    nh_buf[0..2].copy_from_slice(&nh_total.to_ne_bytes());

    // RTA_NEXTHOP has attribute type 3 in the route namespace.
    let nh_attr_total = (4 + nh_buf.len()) as u16;
    let mut raw_nh = Vec::new();
    raw_nh.extend_from_slice(&nh_attr_total.to_ne_bytes());
    raw_nh.extend_from_slice(&(3u16).to_ne_bytes()); // RTA_NEXTHOP = 3
    raw_nh.extend_from_slice(&nh_buf);

    // Append as a raw (unknown) route attribute.
    // netlink-packet-route 0.19 does not have a typed NextHop variant,
    // so we use the catch-all Other variant (kind = 3 for RTA_NEXTHOP).
    route_msg.attributes.push(RouteAttribute::Other(DefaultNla::new(3, raw_nh)));

    // Build netlink message
    let mut header = NetlinkHeader::default();
    header.sequence_number = 1;
    header.flags = NLM_F_REQUEST | NLM_F_ACK | NLM_F_CREATE | NLM_F_REPLACE;
    let mut nl_msg = NetlinkMessage::new(
        header,
        NetlinkPayload::from(RouteNetlinkMessage::NewRoute(route_msg)),
    );
    nl_msg.finalize();

    let socket = Socket::new(NETLINK_ROUTE).context("open NETLINK_ROUTE socket")?;
    let mut nl_buf = vec![0u8; nl_msg.buffer_len()];
    nl_msg.serialize(&mut nl_buf);
    socket
        .send(&nl_buf, 0)
        .context("send RTM_NEWROUTE")?;

    // Wait for ACK (or error)
    let mut buf = vec![0u8; 4096];
    let len = socket.recv(&mut buf, 0).context("recv netlink ACK")?;
    buf.truncate(len);

    let ack_msg: NetlinkMessage<RouteNetlinkMessage> =
        NetlinkMessage::deserialize(&buf).context("deserialize netlink ACK")?;
    if let NetlinkPayload::Error(e) = ack_msg.payload {
        if e.code.is_some() {
            anyhow::bail!(
                "netlink RTM_NEWROUTE failed for default via {} dev {} onlink: {:?}",
                gateway,
                ifname,
                e,
            );
        }
    }

    Ok(())
}

